CREATE TABLE IF NOT EXISTS schema_migrations(version integer PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE organizations(id uuid PRIMARY KEY, name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE users(id uuid PRIMARY KEY, email text NOT NULL UNIQUE, name text NOT NULL, password_hash text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE memberships(org_id uuid REFERENCES organizations, user_id uuid REFERENCES users, role text NOT NULL CHECK(role IN('owner','maintainer','viewer')), active boolean NOT NULL DEFAULT true, PRIMARY KEY(org_id,user_id));
CREATE TABLE sessions(token_hash text PRIMARY KEY,user_id uuid NOT NULL REFERENCES users, org_id uuid NOT NULL REFERENCES organizations, csrf text NOT NULL, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE projects(id uuid PRIMARY KEY,org_id uuid NOT NULL REFERENCES organizations,name text NOT NULL,description text NOT NULL DEFAULT '',repo_path text,module_paths jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(org_id,id));
CREATE TABLE environments(id uuid PRIMARY KEY,org_id uuid NOT NULL,project_id uuid NOT NULL,name text NOT NULL,base_url text NOT NULL,allowed_origins jsonb NOT NULL DEFAULT '[]',build_path text,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(org_id,id),FOREIGN KEY(org_id,project_id) REFERENCES projects(org_id,id));
CREATE TABLE secret_refs(id uuid PRIMARY KEY,org_id uuid NOT NULL,environment_id uuid NOT NULL,name text NOT NULL,payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(org_id,id),UNIQUE(environment_id,name),FOREIGN KEY(org_id,environment_id) REFERENCES environments(org_id,id));
CREATE TABLE requirements(id uuid PRIMARY KEY,org_id uuid NOT NULL,project_id uuid NOT NULL,requirement_key uuid NOT NULL,revision int NOT NULL,title text NOT NULL,body text NOT NULL,hash text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(org_id,id),UNIQUE(requirement_key,revision),FOREIGN KEY(org_id,project_id) REFERENCES projects(org_id,id));
CREATE TABLE discoveries(id uuid PRIMARY KEY,org_id uuid NOT NULL,environment_id uuid NOT NULL,state text NOT NULL DEFAULT 'queued',pages jsonb NOT NULL DEFAULT '[]',error text,limits jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),finished_at timestamptz,UNIQUE(org_id,id),FOREIGN KEY(org_id,environment_id) REFERENCES environments(org_id,id));
CREATE TABLE cases(id uuid PRIMARY KEY,org_id uuid NOT NULL,project_id uuid NOT NULL,current_version int NOT NULL DEFAULT 1,archived boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(org_id,id),FOREIGN KEY(org_id,project_id) REFERENCES projects(org_id,id));
CREATE TABLE case_versions(id uuid PRIMARY KEY,org_id uuid NOT NULL,case_id uuid NOT NULL,version int NOT NULL,title text NOT NULL,module text NOT NULL,priority text NOT NULL,definition jsonb NOT NULL,source_ids jsonb NOT NULL,hash text NOT NULL,origin text NOT NULL,status text NOT NULL DEFAULT 'draft',approved_by uuid REFERENCES users,approved_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(org_id,id),UNIQUE(case_id,version),FOREIGN KEY(org_id,case_id) REFERENCES cases(org_id,id));
CREATE TABLE suites(id uuid PRIMARY KEY,org_id uuid NOT NULL,project_id uuid NOT NULL,name text NOT NULL,version_ids jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(org_id,id),FOREIGN KEY(org_id,project_id) REFERENCES projects(org_id,id));
CREATE TABLE runs(id uuid PRIMARY KEY,org_id uuid NOT NULL,project_id uuid NOT NULL,environment_id uuid NOT NULL,suite_id uuid,actor_id uuid REFERENCES users,state text NOT NULL DEFAULT 'queued',verdict text NOT NULL DEFAULT 'pending',trigger text NOT NULL DEFAULT 'manual',manifest jsonb NOT NULL,manifest_hash text NOT NULL,idempotency_key text NOT NULL,request_hash text NOT NULL,build_before jsonb,build_after jsonb,build_status text NOT NULL DEFAULT 'unverified',error text,created_at timestamptz NOT NULL DEFAULT now(),started_at timestamptz,finished_at timestamptz,heartbeat_at timestamptz,UNIQUE(org_id,id),UNIQUE(org_id,idempotency_key),FOREIGN KEY(org_id,project_id) REFERENCES projects(org_id,id),FOREIGN KEY(org_id,environment_id) REFERENCES environments(org_id,id),FOREIGN KEY(org_id,suite_id) REFERENCES suites(org_id,id));
CREATE TABLE run_cases(id uuid PRIMARY KEY,org_id uuid NOT NULL,run_id uuid NOT NULL,version_id uuid NOT NULL,ordinal int NOT NULL,title text NOT NULL,state text NOT NULL DEFAULT 'pending',outcome text,UNIQUE(org_id,id),UNIQUE(run_id,version_id),FOREIGN KEY(org_id,run_id) REFERENCES runs(org_id,id),FOREIGN KEY(org_id,version_id) REFERENCES case_versions(org_id,id));
CREATE TABLE attempts(id uuid PRIMARY KEY,org_id uuid NOT NULL,run_case_id uuid NOT NULL,number int NOT NULL,state text NOT NULL,steps jsonb NOT NULL DEFAULT '[]',error text,duration_ms int NOT NULL DEFAULT 0,cleanup_ok boolean,assertions int NOT NULL DEFAULT 0,browser_version text,created_at timestamptz NOT NULL DEFAULT now(),finished_at timestamptz,UNIQUE(org_id,id),UNIQUE(run_case_id,number),FOREIGN KEY(org_id,run_case_id) REFERENCES run_cases(org_id,id));
CREATE TABLE artifacts(id uuid PRIMARY KEY,org_id uuid NOT NULL,attempt_id uuid NOT NULL,kind text NOT NULL,storage_key text NOT NULL,bytes bigint NOT NULL,sha256 text NOT NULL,expires_at timestamptz NOT NULL DEFAULT now()+interval '30 days',deleted_at timestamptz,UNIQUE(org_id,id),FOREIGN KEY(org_id,attempt_id) REFERENCES attempts(org_id,id));
CREATE TABLE run_events(seq bigserial PRIMARY KEY,org_id uuid NOT NULL,run_id uuid NOT NULL,type text NOT NULL,payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(org_id,run_id) REFERENCES runs(org_id,id));
CREATE TABLE ai_requests(id uuid PRIMARY KEY,org_id uuid NOT NULL,project_id uuid NOT NULL,state text NOT NULL DEFAULT 'queued',context jsonb NOT NULL,context_hash text NOT NULL,prompt_version text NOT NULL DEFAULT '1',model text,usage jsonb,result_ids jsonb NOT NULL DEFAULT '[]',questions jsonb NOT NULL DEFAULT '[]',error text,created_at timestamptz NOT NULL DEFAULT now(),finished_at timestamptz,UNIQUE(org_id,id),FOREIGN KEY(org_id,project_id) REFERENCES projects(org_id,id));
CREATE TABLE subscriptions(org_id uuid PRIMARY KEY REFERENCES organizations,plan text NOT NULL DEFAULT 'studio',state text NOT NULL DEFAULT 'trial',billing_mode text NOT NULL DEFAULT 'demo' CHECK(billing_mode='demo'),period_end timestamptz NOT NULL DEFAULT now()+interval '30 days');
CREATE TABLE usage_ledger(id bigserial PRIMARY KEY,org_id uuid NOT NULL REFERENCES organizations,event_key text NOT NULL,metric text NOT NULL,amount numeric NOT NULL,reference_id uuid,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(org_id,event_key,metric));
CREATE TABLE reservations(id uuid PRIMARY KEY,org_id uuid NOT NULL REFERENCES organizations,metric text NOT NULL,amount numeric NOT NULL,reference_id uuid NOT NULL,expires_at timestamptz NOT NULL,UNIQUE(org_id,reference_id,metric));
CREATE TABLE schedules(id uuid PRIMARY KEY,org_id uuid NOT NULL,project_id uuid NOT NULL,environment_id uuid NOT NULL,suite_id uuid NOT NULL,actor_id uuid NOT NULL REFERENCES users,name text NOT NULL,cron text NOT NULL,timezone text NOT NULL,enabled boolean NOT NULL DEFAULT true,next_fire timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(org_id,id),FOREIGN KEY(org_id,project_id) REFERENCES projects(org_id,id),FOREIGN KEY(org_id,environment_id) REFERENCES environments(org_id,id),FOREIGN KEY(org_id,suite_id) REFERENCES suites(org_id,id));
CREATE TABLE schedule_fires(id uuid PRIMARY KEY,org_id uuid NOT NULL,schedule_id uuid NOT NULL,scheduled_at timestamptz NOT NULL,run_id uuid,state text NOT NULL,reason text,UNIQUE(schedule_id,scheduled_at),FOREIGN KEY(org_id,schedule_id) REFERENCES schedules(org_id,id));
CREATE TABLE change_sets(id uuid PRIMARY KEY,org_id uuid NOT NULL,project_id uuid NOT NULL,base_sha text NOT NULL,head_sha text NOT NULL,files jsonb NOT NULL,selection jsonb NOT NULL,reason text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(org_id,project_id) REFERENCES projects(org_id,id));
CREATE TABLE outbox(id uuid PRIMARY KEY,org_id uuid NOT NULL REFERENCES organizations,kind text NOT NULL,resource_id uuid NOT NULL,delivered_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(kind,resource_id));
CREATE TABLE audit_events(id bigserial PRIMARY KEY,org_id uuid NOT NULL REFERENCES organizations,actor_id uuid,type text NOT NULL,resource_id uuid,details jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX runs_org_created ON runs(org_id,created_at DESC,id);
CREATE INDEX events_run_seq ON run_events(org_id,run_id,seq);
CREATE INDEX case_versions_lookup ON case_versions(org_id,case_id,version);
CREATE INDEX usage_period ON usage_ledger(org_id,metric,created_at);
CREATE INDEX outbox_pending ON outbox(org_id,created_at) WHERE delivered_at IS NULL;
CREATE INDEX schedules_due ON schedules(org_id,next_fire) WHERE enabled;
CREATE OR REPLACE FUNCTION immutable_case_content() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF ROW(NEW.definition,NEW.hash,NEW.source_ids,NEW.title,NEW.module,NEW.priority,NEW.version,NEW.case_id,NEW.org_id) IS DISTINCT FROM ROW(OLD.definition,OLD.hash,OLD.source_ids,OLD.title,OLD.module,OLD.priority,OLD.version,OLD.case_id,OLD.org_id) THEN RAISE EXCEPTION 'Case version content is immutable'; END IF; RETURN NEW; END $$;
CREATE TRIGGER immutable_case BEFORE UPDATE ON case_versions FOR EACH ROW EXECUTE FUNCTION immutable_case_content();
INSERT INTO schema_migrations(version) VALUES(1);
